const data = $('Deduplicate & Group Keywords').item.json;
const spreadsheetId = $('Extract Sheet ID').item.json.spreadsheet_id;

// Worksheet 1: Bereinigte Keywordliste (1 Keyword pro Gruppe)
const sheet1Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition', 'Status', 'Keyword-Gruppe', 'Variationen'];
const sheet1Rows = data.cleaned_keywords.map(kw => [
  kw.keyword,
  kw.search_volume,
  kw.search_intent,
  kw.cpc,
  kw.competition,
  kw.status,
  kw.group_id,
  kw.variations_count
]);

// Worksheet 2: Komplette Keywordliste (alle Keywords inkl. Variationen)
const sheet2Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition'];
const sheet2Rows = data.complete_keywords.map(kw => [
  kw.keyword,
  kw.search_volume,
  kw.search_intent,
  kw.cpc,
  kw.competition
]);

// Worksheet 3: Keyword-Gruppen (zeigt Zuordnung: welche Keywords gehören zusammen)
const sheet3Header = ['Gruppen-ID', 'Hauptkeyword', 'Keyword-Variation', 'Suchvolumen', 'Search Intent', 'Ist Hauptkeyword'];
const sheet3Rows = data.keyword_groups.map(g => [
  g.group_id,
  g.primary_keyword,
  g.keyword,
  g.search_volume,
  g.search_intent,
  g.is_primary ? 'Ja' : 'Nein'
]);

return [{
  json: {
    spreadsheet_id: spreadsheetId,
    batch_data: {
      valueInputOption: 'RAW',
      data: [
        {
          range: 'Bereinigte Keywordliste!A1',
          values: [sheet1Header, ...sheet1Rows]
        },
        {
          range: 'Komplette Keywordliste!A1',
          values: [sheet2Header, ...sheet2Rows]
        },
        {
          range: 'Keyword-Gruppen!A1',
          values: [sheet3Header, ...sheet3Rows]
        }
      ]
    },
    stats: data.stats
  }
}];

// Pro Keyword-GRUPPE eine ClickUp-Aufgabe erstellen
const data = $('Deduplicate & Group Keywords').item.json;
const cleanedKeywords = data.cleaned_keywords;
const extractData = $('Extract Task Data').item.json;
const themenCluster = extractData.themen_cluster;
const themenClusterValue = extractData.themen_cluster_value;
const kunde = extractData.kunde;

// Pro Gruppe EIN Task (Hauptkeyword = Task-Name)
return cleanedKeywords.map(kw => ({
  json: {
    keyword: kw.keyword,
    search_volume: kw.search_volume,
    search_intent: kw.search_intent,
    themen_cluster: themenCluster,
    themen_cluster_value: themenClusterValue,
    kunde: kunde,
    status: 'keyword',
    variations: kw.variations || '',
    variations_count: kw.variations_count || 1
  }
}));

